import type { CTSProject } from './cts-project-model';
import type { CTSTask } from './cts-task-model';
import type { SystemUser } from './system-user-model';

export const CTSDocumentStatusKeyToLabel = {
  'Draft': 'Draft',
  'Submitted': 'Submitted',
  'Approved': 'Approved',
  'Rejected': 'Rejected',
  'RevisionRequired': 'Revision Required'
} as const;
export type CTSDocumentStatusKey = keyof typeof CTSDocumentStatusKeyToLabel;

export interface CTSDocument {
  /**
   * @displayName CTS Document
   * @description Unique system identifier - GUID generated by system
   * @uiConstraints NEVER create input fields for this ID
   */
  id: string;
  /**
   * @displayName Document Name
   * @description Human-readable record identifier
   * @validationRule Required for create/update operations
   */
  documentName: string;
  /**
   * @displayName Comments
   */
  comments?: string;
  /**
   * @displayName Document URL
   */
  documentURL?: string;
  /**
   * @displayName File Size MB
   */
  fileSizeMB?: number;
  /**
   * @displayName Project
   */
  project?: Pick<CTSProject, 'id' | 'projectName'>;
  /**
   * @displayName SharePoint File ID
   * @validationRule Required for create/update operations
   */
  sharePointFileID: string;
  /**
   * @displayName Status
   */
  statusKey?: CTSDocumentStatusKey;
  /**
   * @displayName Task
   */
  task?: Pick<CTSTask, 'id' | 'taskName'>;
  /**
   * @displayName Uploaded By
   */
  uploadedBy?: Pick<SystemUser, 'id' | 'fullName'>;
  /**
   * @displayName Uploaded Date
   */
  uploadedDate?: string;
  /**
   * @displayName Version Number
   */
  versionNumber?: string;
}

export const _CTSDocument = 'CTSDocument' as const;